contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        c.setOwner(newOwner);
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
